package com.tanidikvar.api.verification.service;
import com.tanidikvar.api.common.error.DomainException;import com.tanidikvar.api.verification.dto.*;import com.tanidikvar.api.verification.repository.EducationVerificationRepository;import java.nio.charset.StandardCharsets;import java.security.*;import java.time.*;import java.util.*;import org.springframework.context.ApplicationEventPublisher;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class EducationVerificationService{private final EducationVerificationRepository repository;private final ApplicationEventPublisher events;private final SecureRandom random=new SecureRandom();public EducationVerificationService(EducationVerificationRepository repository,ApplicationEventPublisher events){this.repository=repository;this.events=events;}
 @Transactional public void request(UUID user,SchoolEmailRequest request){String email=request.email().trim().toLowerCase(Locale.ROOT);if(!repository.eligible(user))throw new DomainException(403,"STUDENT_PROFILE_REQUIRED","Öğrenci profili gerekli.");if(!email.matches("^[^@]+@[^@]+\\.edu\\.tr$"))throw new DomainException(400,"SCHOOL_EMAIL_REQUIRED","Geçerli bir okul e-postası kullan.");String code=String.format(Locale.ROOT,"%06d",random.nextInt(1_000_000));repository.request(user,email,hash(code),Instant.now().plus(Duration.ofMinutes(15)));events.publishEvent(new EducationVerificationMailEvent(email,code));}
 @Transactional public EducationVerificationResponse confirm(UUID user,SchoolEmailConfirmRequest request){if(!repository.confirm(user,hash(request.code())))throw new DomainException(400,"INVALID_VERIFICATION_CODE","Kod geçersiz veya süresi dolmuş.");return repository.get(user);}
 @Transactional public void graduate(UUID user,GraduateVerificationRequest request){if(!repository.graduate(user))throw new DomainException(403,"GRADUATE_PROFILE_REQUIRED","Mezun profili ve program bilgisi gerekli.");repository.graduateRequest(user,request.evidence());}
 @Transactional(readOnly=true)public EducationVerificationResponse get(UUID user){return repository.get(user);}
 private String hash(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}}
